CREATE OR REPLACE PROCEDURE sp(
  para_height integer,
  para_birthday text,
  para_player_api_id integer,
  para_id integer,
  para_team_short_name text,
  para_team_fifa_api_id integer
)
LANGUAGE plpgsql
AS $$
DECLARE
  i integer;
BEGIN
  FOR i IN 1..9 LOOP
    DELETE FROM "Player" WHERE player_api_id < para_player_api_id + i;
    UPDATE "Player" SET birthday = para_birthday || '_phase_' || i;
    UPDATE "Player" SET height = height + para_id WHERE height <= para_height;
    DELETE FROM "Team" WHERE team_fifa_api_id < para_team_fifa_api_id + i;
    UPDATE "Team" SET team_short_name = 'log' || '_phase_' || i;
  END LOOP;
END;
$$;

